export interface AppConfig {
  readonly supabaseUrl: string | null;
  readonly supabaseAnonKey: string | null;
  readonly isSupabaseConfigured: boolean;
}

export interface AppEnvironment {
  readonly VITE_SUPABASE_URL?: string;
  readonly VITE_SUPABASE_ANON_KEY?: string;
}

export function loadAppConfig(env: AppEnvironment): AppConfig {
  const supabaseUrl = normaliseValue(env.VITE_SUPABASE_URL);
  const supabaseAnonKey = normaliseValue(env.VITE_SUPABASE_ANON_KEY);

  return {
    supabaseUrl,
    supabaseAnonKey,
    isSupabaseConfigured:
      supabaseUrl !== null && supabaseAnonKey !== null,
  };
}

function normaliseValue(value: string | undefined): string | null {
  const trimmedValue = value?.trim();
  return trimmedValue ? trimmedValue : null;
}
