import { LitElement, css, html } from 'lit';
import { customElement, property } from 'lit/decorators.js';
import { sharedStyles } from '../styles/shared-styles';

@customElement('setup-card')
export class SetupCard extends LitElement {
  @property({ type: Boolean })
  configured = false;

  static override styles = [
    sharedStyles,
    css`
      :host {
        display: block;
      }

      article {
        background: var(--color-surface);
        border: 1px solid var(--color-border);
        border-radius: 1.5rem;
        box-shadow: var(--shadow-card);
        overflow: hidden;
        padding: clamp(1.5rem, 5vw, 3rem);
        position: relative;
      }

      article::after {
        background: var(--color-accent);
        border-radius: 999px;
        content: "";
        height: 8rem;
        position: absolute;
        right: -3rem;
        top: -4rem;
        transform: rotate(-18deg);
        width: 8rem;
      }

      h2 {
        font-size: clamp(1.75rem, 5vw, 2.75rem);
        letter-spacing: -0.05em;
        line-height: 1;
        margin: 0;
        max-width: 12ch;
      }

      p:not(.eyebrow) {
        color: var(--color-muted);
        line-height: 1.65;
        margin: 1.25rem 0 0;
        max-width: 58ch;
      }

      .status {
        align-items: center;
        background: #f7f7f3;
        border-radius: 1rem;
        display: flex;
        gap: 0.75rem;
        margin-top: 2rem;
        padding: 1rem;
      }

      .dot {
        background: var(--status-color);
        border-radius: 50%;
        box-shadow: 0 0 0 5px color-mix(in srgb, var(--status-color) 18%, transparent);
        flex: 0 0 auto;
        height: 0.75rem;
        width: 0.75rem;
      }

      .status strong {
        display: block;
        font-size: 0.9rem;
      }

      .status span:last-child {
        color: var(--color-muted);
        display: block;
        font-size: 0.8rem;
        margin-top: 0.15rem;
      }
    `,
  ];

  protected override render() {
    const statusColor = this.configured ? '#2a8c5b' : '#d28129';

    return html`
      <article>
        <p class="eyebrow">Étape 1 · Socle technique</p>
        <h2>L’espace membres prend forme.</h2>
        <p>
          L’application est isolée du site public et prête à accueillir
          l’authentification sécurisée, les membres et les événements.
        </p>
        <div
          class="status"
          style=${`--status-color: ${statusColor}`}
          role="status"
        >
          <span class="dot" aria-hidden="true"></span>
          <span>
            <strong>
              ${this.configured
                ? 'Connexion Supabase configurée'
                : 'Configuration Supabase en attente'}
            </strong>
            <span>
              ${this.configured
                ? 'Le socle est prêt pour la prochaine étape.'
                : 'Suivez le guide docs/01-socle-technique.md.'}
            </span>
          </span>
        </div>
      </article>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'setup-card': SetupCard;
  }
}
