import { LitElement, css, html } from 'lit';
import { customElement } from 'lit/decorators.js';
import { loadAppConfig } from '../../config/app-config';
import { sharedStyles } from '../styles/shared-styles';
import './setup-card';

@customElement('dah-app')
export class DahApp extends LitElement {
  private readonly config = loadAppConfig(import.meta.env);

  static override styles = [
    sharedStyles,
    css`
      :host {
        background:
          radial-gradient(circle at 10% 5%, rgb(105 54 201 / 14%), transparent 28rem),
          var(--color-background);
        display: block;
        min-height: 100vh;
      }

      main {
        margin: 0 auto;
        max-width: 70rem;
        padding: clamp(1.25rem, 5vw, 4rem);
      }

      header {
        align-items: center;
        display: flex;
        justify-content: space-between;
        margin-bottom: clamp(3rem, 8vw, 7rem);
      }

      .brand {
        align-items: center;
        display: flex;
        gap: 0.8rem;
      }

      .mark {
        align-items: center;
        background: var(--color-brand);
        border-radius: 0.85rem;
        color: white;
        display: inline-flex;
        font-size: 1.25rem;
        font-weight: 900;
        height: 2.75rem;
        justify-content: center;
        transform: rotate(-4deg);
        width: 2.75rem;
      }

      .brand-name {
        font-size: 1rem;
        font-weight: 850;
        letter-spacing: -0.02em;
      }

      .access {
        color: var(--color-muted);
        font-size: 0.82rem;
        font-weight: 650;
      }

      setup-card {
        margin: 0 auto;
        max-width: 47rem;
      }

      footer {
        color: var(--color-muted);
        font-size: 0.75rem;
        margin-top: 2rem;
        text-align: center;
      }

      @media (max-width: 36rem) {
        .access {
          display: none;
        }
      }
    `,
  ];

  protected override render() {
    return html`
      <main>
        <header>
          <div class="brand" aria-label="DahultiApp">
            <span class="mark" aria-hidden="true">D</span>
            <span class="brand-name">DahultiApp</span>
          </div>
          <span class="access">Accès réservé aux membres</span>
        </header>

        <setup-card .configured=${this.config.isSupabaseConfigured}></setup-card>

        <footer>Dahultimate · Annecy</footer>
      </main>
    `;
  }
}

declare global {
  interface HTMLElementTagNameMap {
    'dah-app': DahApp;
  }
}
